import{_ as e,a,b as r,c as s}from"./chunks/presets-04.Dx-DqE4-.js";import{_ as i,o,c as n,a3 as l}from"./chunks/framework.D1iekJsc.js";const P=JSON.parse('{"title":"Presets","description":"MiniTavern 프롬프트 프리셋. 기본 프롬프트와 정렬 가능한 목록으로 롤플레이 문체를 바꿉니다. 샘플링은 모델 설정에 있습니다.","frontmatter":{"title":"Presets","description":"MiniTavern 프롬프트 프리셋. 기본 프롬프트와 정렬 가능한 목록으로 롤플레이 문체를 바꿉니다. 샘플링은 모델 설정에 있습니다.","head":[["meta",{"name":"keywords","content":"주점,AI 주점,MiniTavern,AI 파트너,AI 친구,AI 로컬 채팅,Silly Tavern,SillyTavern,모바일 Silly Tavern,Silly Tavern 모바일,Silly Tavern 안드로이드,Silly Tavern iOS,AI 롤플레이,캐릭터 카드,AI 채팅,모바일 AI,오프라인 AI,AI 스토리,로컬 LLM,Ollama,LM Studio,세계관,정규식,BYOK,사용자 가이드,매뉴얼"}],["meta",{"property":"og:title","content":"Presets · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern 프롬프트 프리셋. 기본 프롬프트와 정렬 가능한 목록으로 롤플레이 문체를 바꿉니다. 샘플링은 모델 설정에 있습니다."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ko/manual/presets"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ko/manual/presets"}]]},"headers":[],"relativePath":"ko/manual/presets.md","filePath":"ko/manual/presets.md","lastUpdated":1791862671000}'),p={name:"ko/manual/presets.md"};function g(c,t,h,m,d,u){return o(),n("div",null,[...t[0]||(t[0]=[l('<h1 id="presets" tabindex="-1">Presets <a class="header-anchor" href="#presets" aria-label="Permalink to &quot;Presets&quot;">​</a></h1><p>경로: 하단 <strong>설정</strong> → <strong>Presets</strong>.</p><p>프리셋은 프롬프트 구조 한 벌입니다. 롤플레이 문체와 제약을 바꿉니다. 온도 같은 샘플링은 여기가 아니라 <strong>모델 설정</strong>에 있습니다.</p><h2 id="단계" tabindex="-1">단계 <a class="header-anchor" href="#단계" aria-label="Permalink to &quot;단계&quot;">​</a></h2><div class="shot-flow"><figure class="shot-step"><img src="'+e+'" alt="설정의 Presets"><figcaption>1 · 설정 → Presets</figcaption></figure><figure class="shot-step"><img src="'+a+'" alt="프리셋 목록"><figcaption>2 · 목록과 New</figcaption></figure><figure class="shot-step"><img src="'+r+'" alt="프리셋 편집"><figcaption>3 · Name, Basic prompts, Prompts</figcaption></figure><figure class="shot-step"><img src="'+s+'" alt="프롬프트 새로 만들기"><figcaption>4 · 새 프롬프트</figcaption></figure></div><p>이 화면의 버튼 이름은 앱에서 영어입니다.</p><h2 id="목록" tabindex="-1">목록 <a class="header-anchor" href="#목록" aria-label="Permalink to &quot;목록&quot;">​</a></h2><ol><li><strong>New</strong>로 새로 만들거나 SillyTavern Chat Completion 프리셋을 가져옵니다. 샘플링 항목은 무시되고, 모델 설정에서 맞추라고 안내합니다.</li><li>처음에는 <strong>기본</strong> 표시가 붙은 항목만 있습니다. 편집하거나 지울 수 없습니다.</li><li>행 메뉴에서 맨 위로 옮기기, 기본으로 지정, 편집, 복제, 내보내기, 삭제가 됩니다.</li><li>새로 만들기와 복제는 먼저 편집 화면으로 가고, <strong>Save</strong> 한 뒤에 목록에 나타납니다.</li></ol><h2 id="프리셋-편집" tabindex="-1">프리셋 편집 <a class="header-anchor" href="#프리셋-편집" aria-label="Permalink to &quot;프리셋 편집&quot;">​</a></h2><ul><li><strong>Name</strong>은 필수입니다.</li><li><strong>Basic prompts</strong>에서 페르소나, 설명, 성격, 시나리오, 예시 대화 시작, 새 대화 시작, 로어북을 바꿉니다.</li><li><strong>Prompts</strong> 목록은 검색할 수 있습니다. 길게 눌러 순서를 바꿉니다. 스위치가 켜진 항목은 일반 전송에 쓰이고, 꺼진 항목은 비활성으로 남아 넣지 않습니다.</li><li><strong>Add</strong>로 새 프롬프트를 만듭니다. 직접 만든 항목은 편집, 복제, 삭제할 수 있습니다. 기본 제공 항목은 이름과 내용만 바꿉니다.</li></ul><p>캐릭터 카드의 메인 프롬프트와 기록 후 지시는 프리셋의 같은 항목보다 우선합니다. 시나리오 본문은 채팅 설정, 캐릭터 카드, Basic prompts의 일반 텍스트 순입니다.</p><p>이어하기, 다시 생성, 스마트 답장은 이 프리셋을 읽지 않습니다. 일반 전송만 목록 순서대로 조립합니다.</p><h2 id="새-프롬프트" tabindex="-1">새 프롬프트 <a class="header-anchor" href="#새-프롬프트" aria-label="Permalink to &quot;새 프롬프트&quot;">​</a></h2><ol><li><strong>Name</strong>은 필수입니다.</li><li><strong>Role</strong>의 처음 값은 SYSTEM이며 바꿀 수 있습니다.</li><li><strong>Injection position</strong>을 <strong>Relative</strong>로 두면 목록의 그 자리에 들어갑니다. <strong>In-chat</strong>일 때만 <strong>Injection depth</strong>가 나오고, 그 깊이로 기록에 넣습니다.</li><li><strong>Content</strong>에 프롬프트를 씁니다. 매크로도 됩니다.</li><li><strong>Save</strong>하면 프리셋 편집으로 돌아갑니다.</li></ol><h2 id="이-채팅만" tabindex="-1">이 채팅만 <a class="header-anchor" href="#이-채팅만" aria-label="Permalink to &quot;이 채팅만&quot;">​</a></h2><p>경로: 대화 → <strong>채팅 설정</strong> → 모델 → <strong>Presets</strong>.</p><p>처음에는 기본 프리셋을 따릅니다. 끄면 이 채팅만 다른 프리셋을 고를 수 있습니다.</p><h2 id="관련" tabindex="-1">관련 <a class="header-anchor" href="#관련" aria-label="Permalink to &quot;관련&quot;">​</a></h2><ul><li><a href="./model-link">모델 연결</a>: 샘플링은 모델 설정</li><li><a href="./persona">페르소나</a> · <a href="./lorebook">월드북</a>: Basic prompts에서 가져올 수 있습니다</li></ul>',19)])])}const v=i(p,[["render",g]]);export{P as __pageData,v as default};
